            'when' => ['any' => [['type' => 'nonempty', 'key' => 'bluelink_refresh_token'], ['type' => 'nonempty', 'key' => 'bluelink_vin']]],
        ],
        // e3dc-notifier ist ein Kerndienst und wird vom Update/Install-All sichergestellt.
