                    ['type' => 'nonempty', 'key' => 'mqtt_hub_sub_soc_topic'],
                    ['type' => 'nonempty', 'key' => 'mqtt_hub_sub_soc_topic_2'],
                    ['type' => 'nonempty', 'key' => 'wb_topic'],
                    ['type' => 'nonempty', 'key' => 'wb2_topic'],
                ],
            ],
        ],
    ];
}

function e3dc_config_auto_install_known_modules() {
    $known = [];
    foreach (e3dc_config_auto_install_rules() as $module => $rule) {
        $known[$module] = [
            'label' => $rule['label'] ?? $module,
            'service' => $rule['service'] ?? '',
            'config_keys' => $rule['config_keys'] ?? [],
            'when' => $rule['when'] ?? [],
        ];
    }
    return $known;
}

function e3dc_config_auto_rule_matches($data, $rule) {
    if (!is_array($rule)) return false;
    if (isset($rule['all']) && is_array($rule['all'])) {
        foreach ($rule['all'] as $part) {
            if (!e3dc_config_auto_rule_matches($data, $part)) return false;
        }
        return true;
    }
    if (isset($rule['any']) && is_array($rule['any'])) {
        foreach ($rule['any'] as $part) {
            if (e3dc_config_auto_rule_matches($data, $part)) return true;
        }
        return false;
    }
    $key = (string)($rule['key'] ?? '');
    $type = (string)($rule['type'] ?? '');
    if ($key === '' || $type === '') return false;
    if ($type === 'enabled') return e3dc_cfg_enabled($data, $key, false);
    if ($type === 'address') return e3dc_cfg_has_address($data, $key);
    $value = trim(e3dc_cfg_scalar($data, $key, ''));
    if ($type === 'nonempty') return $value !== '';
    $normalized = strtolower($value);
    if ($type === 'equals') return $normalized === strtolower(trim((string)($rule['value'] ?? '')));
    if ($type === 'in' || $type === 'not_in') {
        $values = array_map(function($entry) { return strtolower(trim((string)$entry)); }, (array)($rule['values'] ?? []));
        $contained = in_array($normalized, $values, true);
        return $type === 'in' ? $contained : !$contained;
    }
    return false;
}

function e3dc_config_auto_install_config_changed($data, $oldData, $keys) {
    if (!is_array($oldData) || empty($keys)) return false;
    foreach ((array)$keys as $key) {
        $oldVal = e3dc_config_auto_install_comparable_value(array_key_exists($key, $oldData) ? $oldData[$key] : '');
        $newVal = e3dc_config_auto_install_comparable_value(array_key_exists($key, $data) ? $data[$key] : '');
        if ($oldVal !== $newVal) return true;
    }
    return false;
}

function e3dc_config_auto_install_comparable_value($value) {
    return trim((string)$value);
}

function e3dc_configured_service_auto_installs($data) {
    $wanted = [];
    foreach (e3dc_config_auto_install_known_modules() as $module => $info) {
        if (e3dc_config_auto_rule_matches($data, $info['when'] ?? [])) {
            $wanted[$module] = $info;
        }
    }
    return $wanted;
}

function e3dc_config_auto_install_action_label($action) {
    $labels = [
        'install_module' => 'installieren',
        'enable_service' => 'aktivieren',
        'start_service' => 'starten',
        'restart_service' => 'neu starten',
    ];
    return $labels[$action] ?? (string)$action;
}

function e3dc_run_config_auto_install_job($module, $label, $action = 'install_module') {
    if (!preg_match('/^[A-Za-z0-9_.-]+$/', (string)$module)) {
        return ['ok' => false, 'module' => $module, 'label' => $label, 'action' => $action, 'message' => 'ungültiger Modul-Key'];
    }
    $allowedActions = ['install_module', 'enable_service', 'start_service', 'restart_service'];
    if (!in_array($action, $allowedActions, true)) {
        return ['ok' => false, 'module' => $module, 'label' => $label, 'action' => $action, 'message' => 'ungültige Auto-Install-Aktion'];
    }
    if ((string)$module === 'forecast_evidence') {
        $activation = e3dcActivateForecastEvidenceService();
        return [
            'ok' => !empty($activation['success']),
            'module' => $module,
            'label' => $label,
            'action' => $action,
            'message' => (string)($activation['message'] ?? 'Aktivierung der PV-Prognosediagnose fehlgeschlagen.'),
            'forecast_evidence_activation' => $activation,
        ];
    }
    if (e3dc_config_auto_install_is_docker()) {
        return ['ok' => false, 'module' => $module, 'label' => $label, 'action' => $action, 'message' => 'Docker-Installation: keine sudo-/systemd-Installation aus der Config. Config speichern und Container neu starten, damit entrypoint.sh die Dienste startet.'];
    }
    return [
        'ok' => false,
        'module' => $module,
        'label' => $label,
        'action' => $action,
        'privileged_installer_web_enabled' => false,
        'message' => 'Konfiguration wurde gespeichert. Die automatische privilegierte Dienständerung ist bis zu einem eigenen engen Launcher deaktiviert; bitte den Dienst administrativ installieren, aktivieren oder neu starten.',
    ];
}

function e3dc_config_auto_install_missing_candidates($data, $oldData = null) {
    if (e3dc_config_auto_install_is_docker()) return [];
    $candidates = [];
    foreach (e3dc_config_auto_install_known_modules() as $module => $info) {
        $changed = e3dc_config_auto_install_config_changed($data, $oldData, $info['config_keys'] ?? []);
        if (!$changed) continue;
        if (!e3dc_config_auto_rule_matches($data, $info['when'] ?? [])) continue;
        $service = $info['service'] ?? '';
        $state = e3dc_service_unit_state($service);
        $jobs = [];
        if ($service === '' || empty($state['exists'])) {
            $jobs[] = 'install_module';
        } else {
            if (empty($state['enabled'])) $jobs[] = 'enable_service';
            if (empty($state['active'])) {
                $jobs[] = 'start_service';
            } elseif ($changed) {
                $jobs[] = 'restart_service';
            }
        }
        if (!empty($jobs)) {
            $info['jobs'] = array_values(array_unique($jobs));
            $info['state'] = $state;
            $info['config_changed'] = $changed;
            $candidates[$module] = $info;
        }
    }
    return $candidates;
}

function e3dc_config_auto_install_missing_services($data, $oldData = null) {
    $results = [];
    foreach (e3dc_config_auto_install_missing_candidates($data, $oldData) as $module => $info) {
        $moduleOk = true;
        $messages = [];
        foreach ((array)($info['jobs'] ?? ['install_module']) as $action) {
            $result = e3dc_run_config_auto_install_job($module, $info['label'] ?? $module, $action);
            $moduleOk = $moduleOk && !empty($result['ok']);
            $messages[] = e3dc_config_auto_install_action_label($action) . ': ' . ($result['message'] ?? 'keine Ausgabe');
            if (empty($result['ok'])) break;
        }
        $results[] = [
            'ok' => $moduleOk,
            'module' => $module,
            'label' => $info['label'] ?? $module,
            'jobs' => $info['jobs'] ?? ['install_module'],
            'message' => implode('; ', $messages),
        ];
    }
    return $results;
}

function e3dc_config_secret_mode($data = null) {
    $raw = 'standard';
    if (is_array($data) && array_key_exists('config_secret_protection_mode', $data)) {
        $raw = (string)$data['config_secret_protection_mode'];
    }
    $raw = strtolower(str_replace(['-', ' '], '_', trim($raw)));
    return in_array($raw, ['compat', 'compatible', 'compatibility', 'legacy', 'world_readable', '664'], true)
        ? 'compatibility'
        : 'standard';
}

function e3dc_config_secret_file_mode($data = null) {
    return e3dc_config_secret_mode($data) === 'compatibility' ? 0664 : 0660;
}

function e3dc_config_secret_dir_mode($data = null) {
    return e3dc_config_secret_mode($data) === 'compatibility' ? 02775 : 02770;
}

function e3dc_apply_config_secret_permissions($path, $install_user, $data = null) {
    if ($install_user !== '') @chown($path, $install_user);
    @chgrp($path, 'www-data');
    @chmod($path, e3dc_config_secret_file_mode($data));
}

function e3dc_apply_config_backup_dir_permissions($path, $install_user, $data = null) {
    if ($install_user !== '') @chown($path, $install_user);
    @chgrp($path, 'www-data');
    @chmod($path, e3dc_config_secret_dir_mode($data));
}

function e3dc_config_sensitive_key($key) {
    $k = strtolower((string)$key);
    if (preg_match('/(password|passwort|pwd|token|secret|api[_-]?key|apikey|aes|private|chat[_-]?id|web[_-]?pin|refresh[_-]?token)/', $k)) {
        return true;
    }
    return in_array($k, ['hoehe', 'laenge', 'latitude', 'longitude', 'email'], true);
}

function e3dc_config_redact_export_value($key, $value) {
    if (e3dc_config_sensitive_key($key)) {
        return is_array($value) ? [] : '***REDACTED***';
    }
    if (is_array($value)) {
        $redacted = [];
        foreach ($value as $childKey => $childValue) {
            $redacted[$childKey] = e3dc_config_redact_export_value($childKey, $childValue);
        }
        return $redacted;
    }
    return $value;
}

function e3dc_config_redacted_export_data($data) {
    $redacted = [];
    foreach ((array)$data as $key => $value) {
        $redacted[$key] = e3dc_config_redact_export_value($key, $value);
    }
    return $redacted;
}

function e3dc_config_raw_download_pin_enabled($data) {
    if (!is_array($data)) return false;
    $pin = array_key_exists('web_pin', $data) ? $data['web_pin'] : '';
    if (is_array($pin) && array_key_exists('value', $pin)) {
        $pin = $pin['value'];
    }
    if (is_array($pin) || is_object($pin)) return false;
    return trim((string)$pin) !== '';
}

function e3dc_write_existing_v4_json_preserving_owner($file_path, $json_content, $data, $install_user) {
    if (basename((string)$file_path) !== 'e3dc_v4.json') return false;
    if (!file_exists($file_path) || !is_writable($file_path)) return false;
    $fh = @fopen($file_path, 'c+');
    if ($fh === false) return false;
    $ok = false;
    if (@flock($fh, LOCK_EX)) {
        $original = @stream_get_contents($fh);
        if ($original === false) $original = null;
        @rewind($fh);
        $bytes = @fwrite($fh, $json_content);
        if ($bytes === strlen($json_content) && @ftruncate($fh, strlen($json_content)) && @fflush($fh)) {
            $ok = true;
        } elseif ($original !== null) {
            @rewind($fh);
            @fwrite($fh, $original);
            @ftruncate($fh, strlen($original));
            @fflush($fh);
        }
        @flock($fh, LOCK_UN);
    }
    @fclose($fh);
    if ($ok) {
        e3dc_apply_config_secret_permissions($file_path, $install_user, $data);
    }
    return $ok;
}

function e3dc_aux_inverter_prepare_config($data) {
    if (!is_array($data)) return $data;
    $canonicalPrefix = 'direct_marketing_aux_inverter_shelly_';
    $suffixes = ['override', 'ip', 'invert', 'dynamic_unblock_enable', 'unblock_threshold_w'];
    $safe = ['override' => 'local', 'ip' => '', 'invert' => 0, 'dynamic_unblock_enable' => 0, 'unblock_threshold_w' => 3000];
    $readFamily = function($prefix) use ($data, $suffixes) {
        $present = 0;
        foreach ($suffixes as $suffix) {
            if (array_key_exists($prefix . $suffix, $data)) $present++;
        }
        if ($present === 0) return ['state' => 'absent', 'values' => null];
        if ($present !== count($suffixes)) return ['state' => 'partial', 'values' => null];
        $overrideRaw = strtolower(trim((string)$data[$prefix . 'override']));
        if (in_array($overrideRaw, ['1', 'true', 'yes', 'on', 'ein', 'central', 'zentral'], true)) $override = 'central';
        elseif (in_array($overrideRaw, ['0', 'false', 'no', 'off', 'aus', 'local', 'lokal', ''], true)) $override = 'local';
        else return ['state' => 'invalid', 'values' => null];
        $boolValue = function($value) {
            $raw = strtolower(trim((string)$value));
            if (in_array($raw, ['1', 'true', 'yes', 'on', 'ein'], true)) return 1;
            if (in_array($raw, ['0', 'false', 'no', 'off', 'aus', ''], true)) return 0;
            return null;
        };
        $invert = $boolValue($data[$prefix . 'invert']);
        $dynamic = $boolValue($data[$prefix . 'dynamic_unblock_enable']);
        $ip = trim((string)$data[$prefix . 'ip']);
        $thresholdRaw = trim((string)$data[$prefix . 'unblock_threshold_w']);
        $threshold = is_numeric($thresholdRaw) ? (int)round((float)$thresholdRaw) : 0;
        if ($invert === null || $dynamic === null || ($ip !== '' && filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) === false)
            || ($override === 'central' && $ip === '') || $threshold < 100 || $threshold > 100000) {
            return ['state' => 'invalid', 'values' => null];
        }
        return ['state' => 'valid', 'values' => [
            'override' => $override,
            'ip' => $ip,
            'invert' => $invert,
            'dynamic_unblock_enable' => $dynamic,
            'unblock_threshold_w' => $threshold,
        ]];
    };
    $canonical = $readFamily($canonicalPrefix);
    $persistedBlocked = strtolower(trim((string)($data[$canonicalPrefix . 'contract_status'] ?? ''))) === 'blocked';
    $values = $safe;
    $status = 'ok';
    $reason = 'canonical_absent';
    if ($persistedBlocked) {
        $status = 'blocked';
        $reason = (string)($data[$canonicalPrefix . 'contract_reason'] ?? 'persisted_conflict');
    } elseif ($canonical['state'] === 'valid') {
        $values = $canonical['values'];
        $reason = 'canonical_only';
    } elseif ($canonical['state'] !== 'absent') {
        $status = 'blocked';
        $reason = $canonical['state'] === 'partial'
            ? 'config_contract_partial'
            : 'config_contract_invalid';
    }
    foreach ($values as $suffix => $value) {
        $data[$canonicalPrefix . $suffix] = $value;
    }
    $data[$canonicalPrefix . 'contract_status'] = $status;
    $data[$canonicalPrefix . 'contract_reason'] = $reason;
    return $data;
}

function e3dc_write_v4_json($file_path, $data, $install_user) {
    $data = e3dc_aux_inverter_prepare_config($data);
    $json_content = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    if ($json_content === false) return false;
    if (e3dc_write_existing_v4_json_preserving_owner($file_path, $json_content, $data, $install_user)) return true;
    $tmp_file = tempnam(dirname($file_path), '.e3dc_v4_');
    if ($tmp_file === false) return false;
    if (file_put_contents($tmp_file, $json_content) === false) {
        @unlink($tmp_file);
        return false;
    }
    e3dc_apply_config_secret_permissions($tmp_file, $install_user, $data);
    if (!@rename($tmp_file, $file_path)) {
        @unlink($tmp_file);
        return false;
    }
    e3dc_apply_config_secret_permissions($file_path, $install_user, $data);
    return true;
}

function e3dc_read_existing_v4_json($file_path) {
    if (!file_exists($file_path)) return [];
    $raw = @file_get_contents($file_path);
    if ($raw === false) return null;
    $decoded = @json_decode($raw, true);
    return is_array($decoded) ? $decoded : null;
}

function e3dc_config_backup_dir() {
    return '/var/www/html/data/config_backups/';
}

function e3dc_prune_config_backups($limit = 20) {
    return e3dcPruneAutomaticConfigBackups(e3dc_config_backup_dir(), $limit);
}

function e3dc_backup_current_v4_json($file_path, $suffix = '', $options = []) {
    $options = is_array($options) ? $options : [];
    if (empty($options['test_mode'])) {
        $options['backup_dir'] = rtrim(e3dc_config_backup_dir(), '/');
    } elseif (empty($options['backup_dir'])) {
        $options['backup_dir'] = dirname((string)$file_path) . '/config_backups';
    }
    return e3dcCreateConfirmedV4Backup($file_path, $suffix, $options);
}

function e3dc_config_backup_succeeded($backup_result, $source_path = null) {
    if (!is_array($backup_result)
        || empty($backup_result['success'])
        || !is_string($backup_result['path'] ?? null)
        || !hash_equals(
            (string)($backup_result['preimage_sha256'] ?? ''),
            (string)($backup_result['backup_sha256'] ?? '')
        )) {
        return false;
    }
    $backupRaw = e3dcReadRegularFileBound((string)$backup_result['path'], 4 * 1024 * 1024);
    if (!is_string($backupRaw)
        || !hash_equals(hash('sha256', $backupRaw), (string)$backup_result['backup_sha256'])) {
        return false;
    }
    if (is_string($source_path) && $source_path !== '') {
        $sourceRaw = e3dcReadRegularFileBound($source_path, 4 * 1024 * 1024);
        if (!is_string($sourceRaw)
            || !hash_equals(hash('sha256', $sourceRaw), (string)$backup_result['preimage_sha256'])) {
            return false;
        }
    }
    return true;
}

function e3dc_config_retention_warning($result) {
    if (!is_array($result)) return '';
    $warning = $result['backup_retention_warning']
        ?? $result['retention_warning']
        ?? '';
    return is_string($warning) ? trim($warning) : '';
}

function e3dc_config_retention_warning_html($result) {
    $warning = e3dc_config_retention_warning($result);
    if ($warning === '') return '';
    return '<div class="small mt-1"><strong>Hinweis zur Bereinigung:</strong> '
        . htmlspecialchars($warning)
        . '</div>';
}

function e3dc_config_import_local_keys() {
    return ['install_user', 'home_dir', 'install_path', 'venv_name', 'venv_path'];
}

function e3dc_config_preserve_local_keys($current, $next) {
    foreach (e3dc_config_import_local_keys() as $key) {
        if (is_array($current) && array_key_exists($key, $current)) {
            $next[$key] = $current[$key];
        } else {
            unset($next[$key]);
        }
    }
    return $next;
}

function e3dc_config_editor_protected_extra_key($key) {
    $normalized = strtolower(trim((string)$key));
    if ($normalized === '' || str_starts_with($normalized, '_')) return true;
    return in_array($normalized, [
        'stop', 'config', 'schema', 'schema_version', 'version', 'config_version',
        'install_user', 'home_dir', 'install_path', 'venv_name', 'venv_path',
        'instance_role', 'node_id', 'ha_role', 'e3dcwallboxtxt',
        'installer_debug_console', 'logfile', 'ui_energy_flow', 'pvatmosphere',
    ], true);
}

function e3dc_config_editor_stream_is_bound($handle, $filePath) {
    if (!is_resource($handle) || is_link($filePath)) return false;
    $opened = @fstat($handle);
    $named = @lstat($filePath);
    return is_array($opened)
        && is_array($named)
        && ((((int)$opened['mode']) & 0170000) === 0100000)
        && ((((int)$named['mode']) & 0170000) === 0100000)
        && (int)$opened['nlink'] === 1
        && (int)$named['nlink'] === 1
        && (int)$opened['dev'] === (int)$named['dev']
        && (int)$opened['ino'] === (int)$named['ino'];
}

function e3dc_config_editor_write_new_stream($handle, $bytes) {
    if (!is_resource($handle) || !is_string($bytes) || !@rewind($handle)) return false;
    $length = strlen($bytes);
    $written = 0;
    while ($written < $length) {
        $count = @fwrite($handle, substr($bytes, $written));
        if ($count === false || $count <= 0) return false;
        $written += $count;
    }
    if (!@ftruncate($handle, $length) || !@fflush($handle)) return false;
    if (function_exists('fsync') && !@fsync($handle)) return false;
    if (!@rewind($handle)) return false;
    $confirmed = @stream_get_contents($handle);
    return is_string($confirmed)
        && strlen($confirmed) === $length
        && hash_equals(hash('sha256', $bytes), hash('sha256', $confirmed));
}

function e3dc_config_editor_publish_authority($installUser, $groupName = 'www-data') {
    if (!function_exists('posix_geteuid')
        || !function_exists('posix_getpwuid')
        || !function_exists('posix_getpwnam')
        || !function_exists('posix_getgrnam')) {
        return [
            'success' => false,
            'message' => 'Die lokale Benutzer- und Gruppenbindung ist nicht verfügbar.',
        ];
    }
    $installUser = trim((string)$installUser);
    $groupName = trim((string)$groupName);
    $publisherUid = (int)posix_geteuid();
    $publisher = @posix_getpwuid($publisherUid);
    $install = $installUser !== '' ? @posix_getpwnam($installUser) : false;
    $group = $groupName !== '' ? @posix_getgrnam($groupName) : false;
    if (!is_array($publisher) || !is_array($install) || !is_array($group)) {
        return [
            'success' => false,
            'message' => 'Installationsbenutzer, Web-Publisher oder gemeinsame Gruppe konnten nicht gebunden werden.',
        ];
    }
    $publisherName = (string)($publisher['name'] ?? '');
    $installUid = (int)($install['uid'] ?? -1);
    $groupGid = (int)($group['gid'] ?? -1);
    $installInGroup = (int)($install['gid'] ?? -2) === $groupGid
        || in_array($installUser, (array)($group['members'] ?? []), true);
    $publisherInGroup = (int)($publisher['gid'] ?? -2) === $groupGid
        || in_array($publisherName, (array)($group['members'] ?? []), true);
    if (!$installInGroup
        || !$publisherInGroup
        || !in_array($publisherName, [$installUser, 'www-data'], true)) {
        return [
            'success' => false,
            'message' => 'Der Web-Publisher und der Installationsbenutzer sind nicht sicher über die gemeinsame www-data-Gruppe gebunden.',
        ];
    }
    return [
        'success' => true,
        'publisher_uid' => $publisherUid,
        'install_uid' => $installUid,
        'group_gid' => $groupGid,
        'publisher_name' => $publisherName,
    ];
}

function e3dc_config_editor_open_transaction_lock($filePath, array $authority) {
    $directory = dirname((string)$filePath);
    $directoryBefore = @lstat($directory);
    if (!is_array($directoryBefore)
        || ((((int)($directoryBefore['mode'] ?? 0)) & 0170000) !== 0040000)
        || is_link($directory)) {
        return ['success' => false, 'message' => 'Das Konfigurationsverzeichnis ist nicht sicher gebunden.'];
    }

    $lockPath = $directory . '/.e3dc_v4.transaction.lock';
    clearstatcache(true, $lockPath);
    $lockBefore = @lstat($lockPath);
    if (!is_array($lockBefore)) {
        $oldUmask = @umask(0007);
        $handle = @fopen($lockPath, 'x+b');
        if (is_int($oldUmask)) @umask($oldUmask);
        if (!is_resource($handle)) {
            clearstatcache(true, $lockPath);
            $lockBefore = @lstat($lockPath);
            $handle = is_array($lockBefore) ? @fopen($lockPath, 'r+b') : false;
        }
    } else {
        $handle = @fopen($lockPath, 'r+b');
    }
    if (!is_resource($handle)) {
        return ['success' => false, 'message' => 'Der feste Konfigurations-Lock ist nicht verfügbar.'];
    }

    clearstatcache(true, $lockPath);
    $opened = @fstat($handle);
    $named = @lstat($lockPath);
    $allowedOwners = [(int)$authority['install_uid'], (int)$authority['publisher_uid']];
    $metadataOk = is_array($opened)
        && is_array($named)
        && ((((int)($opened['mode'] ?? 0)) & 0170000) === 0100000)
        && ((((int)($named['mode'] ?? 0)) & 0170000) === 0100000)
        && (int)($opened['nlink'] ?? 0) === 1
        && (int)($named['nlink'] ?? 0) === 1
        && (int)($opened['dev'] ?? -1) === (int)($named['dev'] ?? -2)
        && (int)($opened['ino'] ?? -1) === (int)($named['ino'] ?? -2)
        && in_array((int)($opened['uid'] ?? -1), $allowedOwners, true)
        && (int)($opened['gid'] ?? -1) === (int)$authority['group_gid']
        && ((((int)($opened['mode'] ?? 0)) & 0777) === 0660);
    if (!$metadataOk || !@flock($handle, LOCK_EX)) {
        @fclose($handle);
        return [
            'success' => false,
            'message' => 'Der feste Konfigurations-Lock besitzt nicht die erwarteten Rechte oder konnte nicht exklusiv belegt werden.',
        ];
    }
    if (!e3dc_config_editor_stream_is_bound($handle, $lockPath)) {
        @flock($handle, LOCK_UN);
        @fclose($handle);
        return ['success' => false, 'message' => 'Der feste Konfigurations-Lock wurde während der Bindung ausgetauscht.'];
    }
    return [
        'success' => true,
        'handle' => $handle,
        'path' => $lockPath,
        'directory_stat' => $directoryBefore,
    ];
}

function e3dc_config_editor_directory_is_bound($directory, array $expected) {
    if (is_link($directory)) return false;
    $current = @lstat($directory);
    return is_array($current)
        && ((((int)($current['mode'] ?? 0)) & 0170000) === 0040000)
        && (int)($current['dev'] ?? -1) === (int)($expected['dev'] ?? -2)
        && (int)($current['ino'] ?? -1) === (int)($expected['ino'] ?? -2);
}

function e3dc_config_editor_sync_directory($directory, array $expected) {
    if (!function_exists('fsync') || !e3dc_config_editor_directory_is_bound($directory, $expected)) return true;
    $handle = @fopen($directory, 'rb');
    if (!is_resource($handle)) return false;
    $opened = @fstat($handle);
    $bound = is_array($opened)
        && ((((int)($opened['mode'] ?? 0)) & 0170000) === 0040000)
        && (int)($opened['dev'] ?? -1) === (int)($expected['dev'] ?? -2)
        && (int)($opened['ino'] ?? -1) === (int)($expected['ino'] ?? -2);
    $synced = $bound && @fsync($handle);
    @fclose($handle);
    return $synced;
}

function e3dc_config_editor_publish_atomic(
    $filePath,
    $candidateBytes,
    $preimageBytes,
    $targetHandle,
    array $targetStat,
    array $lock,
    array $authority,
    $expectedMode
) {
    $directory = dirname((string)$filePath);
    try {
        $suffix = bin2hex(random_bytes(16));
    } catch (Throwable $error) {
        return ['success' => false, 'message' => 'Die atomare Zieldatei konnte nicht eindeutig benannt werden.'];
    }
    $temporary = $directory . '/.e3dc_v4.extra.' . $suffix . '.tmp';
    $expectedMode = (int)$expectedMode & 0777;
    $oldUmask = @umask((~$expectedMode) & 0777);
    $temporaryHandle = @fopen($temporary, 'x+b');
    if (is_int($oldUmask)) @umask($oldUmask);
    if (!is_resource($temporaryHandle)) {
        return ['success' => false, 'message' => 'Die atomare Zieldatei konnte nicht exklusiv angelegt werden.'];
    }

    $published = false;
    try {
        if (!e3dc_config_editor_write_new_stream($temporaryHandle, $candidateBytes)) {
            return ['success' => false, 'message' => 'Die neue Konfiguration konnte nicht vollständig geschrieben und synchronisiert werden.'];
        }
        clearstatcache(true, $temporary);
        $temporaryStat = @fstat($temporaryHandle);
        $temporaryNamed = @lstat($temporary);
        $temporaryOk = is_array($temporaryStat)
            && is_array($temporaryNamed)
            && ((((int)($temporaryStat['mode'] ?? 0)) & 0170000) === 0100000)
            && (int)($temporaryStat['nlink'] ?? 0) === 1
            && (int)($temporaryStat['dev'] ?? -1) === (int)($temporaryNamed['dev'] ?? -2)
            && (int)($temporaryStat['ino'] ?? -1) === (int)($temporaryNamed['ino'] ?? -2)
            && (int)($temporaryStat['uid'] ?? -1) === (int)$authority['publisher_uid']
            && (int)($temporaryStat['gid'] ?? -1) === (int)$authority['group_gid']
            && ((((int)($temporaryStat['mode'] ?? 0)) & 0777) === ((int)$expectedMode & 0777))
            && (int)($temporaryStat['size'] ?? -1) === strlen($candidateBytes);
        if (!$temporaryOk) {
            return [
                'success' => false,
                'message' => 'Die neue Konfiguration besitzt vor der Veröffentlichung nicht die erwarteten Owner-/Gruppen-/Dateirechte.',
            ];
        }

        if (!e3dc_config_editor_stream_is_bound($lock['handle'], $lock['path'])
            || !e3dc_config_editor_stream_is_bound($targetHandle, $filePath)
            || !e3dc_config_editor_directory_is_bound($directory, $lock['directory_stat'])
            || !@rewind($targetHandle)) {
            return ['success' => false, 'message' => 'Lock, Verzeichnis oder Konfigurations-Preimage sind vor dem Commit gedriftet.'];
        }
        $currentBytes = @stream_get_contents($targetHandle);
        $currentStat = @fstat($targetHandle);
        $preimageStillBound = is_string($currentBytes)
            && hash_equals(hash('sha256', $preimageBytes), hash('sha256', $currentBytes))
            && is_array($currentStat)
            && (int)($currentStat['dev'] ?? -1) === (int)($targetStat['dev'] ?? -2)
            && (int)($currentStat['ino'] ?? -1) === (int)($targetStat['ino'] ?? -2);
        if (!$preimageStillBound) {
            return [
                'success' => false,
                'message' => 'Die Konfiguration wurde parallel geändert. Bitte die Seite neu laden; es wurde nichts überschrieben.',
            ];
        }

        if (!@rename($temporary, $filePath)) {
            return ['success' => false, 'message' => 'Die neue Konfiguration konnte nicht atomar veröffentlicht werden.'];
        }
        $published = true;
        clearstatcache(true, $filePath);
        $publishedStat = @lstat($filePath);
        if (!e3dc_config_editor_stream_is_bound($temporaryHandle, $filePath)
            || !is_array($publishedStat)
            || (int)($publishedStat['uid'] ?? -1) !== (int)$authority['publisher_uid']
            || (int)($publishedStat['gid'] ?? -1) !== (int)$authority['group_gid']
            || ((((int)($publishedStat['mode'] ?? 0)) & 0777) !== ((int)$expectedMode & 0777))
            || !@rewind($temporaryHandle)) {
            return [
                'success' => false,
                'published' => true,
                'message' => 'Die Konfiguration wurde veröffentlicht, der gebundene Readback blieb jedoch unvollständig. Bitte die Seite neu laden und die Rechteprüfung starten.',
            ];
        }
        $confirmedBytes = @stream_get_contents($temporaryHandle);
        if (!is_string($confirmedBytes)
            || !hash_equals(hash('sha256', $candidateBytes), hash('sha256', $confirmedBytes))) {
            return [
                'success' => false,
                'published' => true,
                'message' => 'Die Konfiguration wurde veröffentlicht, ihr Inhalt konnte aber nicht bestätigt werden. Bitte die Seite neu laden und die Konfiguration prüfen.',
            ];
        }
        if (!e3dc_config_editor_sync_directory($directory, $lock['directory_stat'])) {
            return [
                'success' => false,
                'published' => true,
                'message' => 'Die Konfiguration ist vollständig veröffentlicht, die dauerhafte Verzeichnissynchronisation konnte aber nicht bestätigt werden.',
            ];
        }
        return ['success' => true];
    } finally {
        @fclose($temporaryHandle);
        if (!$published && (file_exists($temporary) || is_link($temporary))) {
            @unlink($temporary);
        }
    }
}

function e3dc_config_editor_extra_key_transaction(
    $operation,
    $requestedKey,
    $requestedValue,
    $filePath,
    $installUser,
    array $knownKeys,
    $groupName = 'www-data'
) {
    $operation = (string)$operation;
    $rawKey = trim((string)$requestedKey);
    $key = $operation === 'add' ? strtolower($rawKey) : $rawKey;
    $keyPattern = '/\A[a-z][a-z0-9_.-]{0,127}\z/D';
    if (!in_array($operation, ['add', 'delete'], true) || preg_match($keyPattern, $key) !== 1) {
        return [
            'success' => false,
            'code' => 'invalid_key',
            'message' => 'Der Schlüssel muss mit einem Buchstaben beginnen und darf nur Kleinbuchstaben, Zahlen, Punkt, Bindestrich oder Unterstrich enthalten.',
        ];
    }
    $normalizedKey = strtolower($key);
    $knownSet = [];
    foreach ($knownKeys as $knownKey) {
        $knownSet[strtolower((string)$knownKey)] = true;
    }
    if (isset($knownSet[$normalizedKey]) || e3dc_config_editor_protected_extra_key($normalizedKey)) {
        return [
            'success' => false,
            'code' => 'protected_key',
            'message' => 'Dieser bekannte Pflicht- oder Schutzparameter darf hier weder angelegt noch gelöscht werden.',
        ];
    }
    if ($operation === 'add') {
        if (is_array($requestedValue) || is_object($requestedValue)) {
            return [
                'success' => false,
                'code' => 'invalid_value',
                'message' => 'Der neue Wert muss ein einzelner Text- oder Zahlenwert sein.',
            ];
        }
        $requestedValue = trim((string)$requestedValue);
        if ($requestedValue === '' || strlen($requestedValue) > 65535 || strpos($requestedValue, "\0") !== false) {
            return [
                'success' => false,
                'code' => 'invalid_value',
                'message' => 'Für die neue Variable ist ein nicht leerer Wert mit höchstens 65.535 Zeichen erforderlich.',
            ];
        }
    }

    $authority = e3dc_config_editor_publish_authority($installUser, $groupName);
    if (empty($authority['success'])) {
        return [
            'success' => false,
            'code' => 'publisher_authority_failed',
            'message' => (string)($authority['message'] ?? 'Der Web-Publisher konnte nicht sicher gebunden werden.')
                . ' Bitte im Installationscenter „Rechte prüfen und reparieren“ ausführen.',
        ];
    }
    $directory = dirname((string)$filePath);
    if (basename((string)$filePath) !== 'e3dc_v4.json'
        || !is_dir($directory)
        || is_link($directory)
        || !is_file($filePath)
        || is_link($filePath)) {
        return [
            'success' => false,
            'code' => 'unsafe_context',
            'message' => 'Der Konfigurationspfad ist nicht eindeutig oder nicht sicher.',
        ];
    }
    $lock = e3dc_config_editor_open_transaction_lock($filePath, $authority);
    if (empty($lock['success'])) {
        return [
            'success' => false,
            'code' => 'lock_failed',
            'message' => (string)($lock['message'] ?? 'Die Konfiguration konnte nicht exklusiv gesperrt werden.')
                . ' Bitte die Seite neu laden oder im Installationscenter die Rechte reparieren.',
        ];
    }

    $handle = @fopen($filePath, 'rb');
    if ($handle === false || !e3dc_config_editor_stream_is_bound($handle, $filePath)) {
        if (is_resource($handle)) @fclose($handle);
        @flock($lock['handle'], LOCK_UN);
        @fclose($lock['handle']);
        return [
            'success' => false,
            'code' => 'config_open_failed',
            'message' => 'Die Konfiguration ist nicht eindeutig oder nicht beschreibbar.',
        ];
    }
    if (!@flock($handle, LOCK_EX)) {
        @fclose($handle);
        @flock($lock['handle'], LOCK_UN);
        @fclose($lock['handle']);
        return [
            'success' => false,
            'code' => 'lock_failed',
            'message' => 'Die Konfiguration wird gerade bearbeitet oder konnte nicht exklusiv gesperrt werden.',
        ];
    }

    try {
        if (!e3dc_config_editor_stream_is_bound($handle, $filePath)) {
            return [
                'success' => false,
                'code' => 'concurrent_change',
                'message' => 'Die Konfigurationsdatei wurde während des Sperrens ausgetauscht. Bitte die Seite neu laden.',
            ];
        }
        @rewind($handle);
        $preimageBytes = @stream_get_contents($handle);
        $preimage = is_string($preimageBytes) ? json_decode($preimageBytes, true) : null;
        if (!is_array($preimage)) {
            return [
                'success' => false,
                'code' => 'config_invalid',
                'message' => 'Die aktuelle e3dc_v4.json ist nicht lesbar oder ungültig.',
            ];
        }
        $targetStat = @fstat($handle);
        if (!is_array($targetStat)
            || (int)($targetStat['size'] ?? -1) < 2
            || (int)($targetStat['size'] ?? -1) > 4 * 1024 * 1024
            || strlen($preimageBytes) !== (int)($targetStat['size'] ?? -1)) {
            return [
                'success' => false,
                'code' => 'config_size_invalid',
                'message' => 'Die e3dc_v4.json besitzt keine zulässige und vollständig gebundene Größe.',
            ];
        }
        $expectedMode = e3dc_config_secret_file_mode($preimage);
        $allowedTargetOwners = [(int)$authority['install_uid'], (int)$authority['publisher_uid']];
        $targetMetadataOk = is_array($targetStat)
            && in_array((int)($targetStat['uid'] ?? -1), $allowedTargetOwners, true)
            && (int)($targetStat['gid'] ?? -1) === (int)$authority['group_gid']
            && ((((int)($targetStat['mode'] ?? 0)) & 0777) === ($expectedMode & 0777));
        if (!$targetMetadataOk) {
            return [
                'success' => false,
                'code' => 'config_metadata_invalid',
                'message' => 'Die e3dc_v4.json besitzt nicht den sicheren Install-User-/Web-Publisher-, www-data- und Schutzmodus-Vertrag. Bitte im Installationscenter „Rechte prüfen und reparieren“ ausführen.',
            ];
        }
        $matchingKeys = array_values(array_filter(array_keys($preimage), static function($existingKey) use ($normalizedKey) {
            return strtolower((string)$existingKey) === $normalizedKey;
        }));
        $boundDeleteKey = null;
        if ($operation === 'delete') {
            if (count($matchingKeys) !== 1) {
                return [
                    'success' => false,
                    'code' => 'key_not_bound',
                    'message' => 'Der zusätzliche Parameter ist im frisch gelesenen Konfigurationsstand nicht eindeutig vorhanden.',
                ];
            }
            $boundDeleteKey = (string)$matchingKeys[0];
            if (is_array($preimage[$boundDeleteKey]) || is_object($preimage[$boundDeleteKey])) {
                return [
                    'success' => false,
                    'code' => 'key_not_deletable',
                    'message' => 'Dieser Parameter gehört nicht zur frisch bestätigten Liste „Weitere Parameter“ und wurde nicht gelöscht.',
                ];
            }
        } elseif ($matchingKeys !== []) {
            return [
                'success' => false,
                'code' => 'key_exists',
                'message' => 'Dieser Schlüssel ist bereits vorhanden und wurde nicht überschrieben.',
            ];
        }

        $backupResult = e3dc_backup_current_v4_json(
            $filePath,
            'extra_key',
            ['expected_preimage' => $preimageBytes]
        );
        $backupPath = is_array($backupResult) ? (string)($backupResult['path'] ?? '') : '';
        $backupBytes = $backupPath !== '' ? e3dcReadRegularFileBound($backupPath, 4 * 1024 * 1024) : false;
        if (!e3dc_config_backup_succeeded($backupResult, $filePath)
            || !is_string($backupBytes)
            || !hash_equals(hash('sha256', $preimageBytes), hash('sha256', $backupBytes))) {
            return [
                'success' => false,
                'code' => 'backup_failed',
                'message' => 'Vor der Änderung konnte keine bestätigte Konfigurationssicherung angelegt werden.',
            ];
        }
        if (!e3dcRemoveConfigCacheFailClosed('/var/www/html/ramdisk/e3dc_config_cache.json')) {
            return [
                'success' => false,
                'code' => 'cache_invalidation_failed',
                'message' => 'Der Laufzeitcache konnte vor der Änderung nicht sicher entfernt werden. Bitte im Installationscenter „Rechte prüfen und reparieren“ ausführen.',
            ];
        }

        $candidate = $preimage;
        if ($operation === 'delete') {
            unset($candidate[$boundDeleteKey]);
        } else {
            $candidate[$key] = $requestedValue;
        }
        $candidateBytes = json_encode(
            $candidate,
            JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
        );
        if (!is_string($candidateBytes)) {
            return [
                'success' => false,
                'code' => 'encode_failed',
                'message' => 'Die Konfigurationsänderung konnte nicht sicher kodiert werden.',
            ];
        }
        $candidateBytes .= "\n";
        if (strlen($candidateBytes) > 4 * 1024 * 1024) {
            return [
                'success' => false,
                'code' => 'config_size_invalid',
                'message' => 'Die geänderte e3dc_v4.json überschreitet die zulässige Größe.',
            ];
        }
        $publish = e3dc_config_editor_publish_atomic(
            $filePath,
            $candidateBytes,
            $preimageBytes,
            $handle,
            $targetStat,
            $lock,
            $authority,
            $expectedMode
        );
        if (empty($publish['success'])) {
            return [
                'success' => false,
                'code' => !empty($publish['published']) ? 'published_unconfirmed' : 'publish_failed',
                'message' => (string)($publish['message'] ?? 'Die Konfigurationsänderung konnte nicht atomar bestätigt werden.'),
            ];
        }
        return [
            'success' => true,
            'code' => $operation === 'delete' ? 'key_deleted' : 'key_added',
            'key' => $key,
            'message' => $operation === 'delete'
                ? 'Zusätzlicher Parameter „' . $key . '“ wurde gelöscht.'
                : 'Neue Variable „' . $key . '“ wurde hinzugefügt.',
            'backup_retention_warning' => $backupResult['retention_warning'] ?? null,
        ];
    } finally {
        @flock($handle, LOCK_UN);
        @fclose($handle);
        @flock($lock['handle'], LOCK_UN);
        @fclose($lock['handle']);
    }
}

function e3dc_config_extract_import_payload($decoded) {
    if (!is_array($decoded)) return null;
    if (isset($decoded['config']) && is_array($decoded['config'])) {
        $decoded = $decoded['config'];
    }
    if ($decoded === []) return null;
    $keys = array_keys($decoded);
    if ($keys === range(0, count($decoded) - 1)) return null;
    $clean = [];
    foreach ($decoded as $key => $value) {
        $key = trim((string)$key);
        if ($key === '' || $key === 'stop') continue;
        if (!preg_match('/^[A-Za-z0-9_.-]+$/', $key)) return null;
        $clean[$key] = $value;
    }
    return $clean;
}

function e3dc_tibber_format_ct($value) {
    return number_format((float)$value, 2, ',', '.');
}

function e3dc_entsoe_api_time($ts) {
    return gmdate('YmdHi', (int)$ts);
}

function e3dc_entsoe_parse_resolution_s($text) {
    $value = strtoupper(trim((string)$text));
    if ($value === 'PT15M') return 15 * 60;
    if ($value === 'PT30M') return 30 * 60;
    if ($value === 'PT60M' || $value === 'PT1H') return 60 * 60;
    if (preg_match('/^PT([0-9]+(?:\.[0-9]+)?)([HM])$/', $value, $m)) {
        $amount = (float)$m[1];
        return (int)round($amount * ($m[2] === 'H' ? 3600 : 60));
    }
    return 0;
}

function e3dc_entsoe_xml_blocks($raw, $tag) {
    $safeTag = preg_quote($tag, '/');
    $pattern = '/<(?:(?:[A-Za-z0-9_]+):)?' . $safeTag . '\b[^>]*>(.*?)<\/(?:(?:[A-Za-z0-9_]+):)?' . $safeTag . '>/is';
    if (!preg_match_all($pattern, (string)$raw, $matches)) return [];
    return $matches[1] ?? [];
}

function e3dc_entsoe_xml_text($raw, $tag) {
    $blocks = e3dc_entsoe_xml_blocks($raw, $tag);
    if (!$blocks) return '';
    return trim(html_entity_decode((string)$blocks[0], ENT_QUOTES | ENT_XML1, 'UTF-8'));
}

function e3dc_entsoe_parse_day_ahead_xml($raw) {
    $slots = [];
    $timeSeries = e3dc_entsoe_xml_blocks($raw, 'TimeSeries');
    foreach ($timeSeries as $series) {
        $periods = e3dc_entsoe_xml_blocks($series, 'Period');
        foreach ($periods as $period) {
            $timeInterval = e3dc_entsoe_xml_text($period, 'timeInterval');
            $startText = e3dc_entsoe_xml_text($timeInterval, 'start');
            $resolutionText = e3dc_entsoe_xml_text($period, 'resolution');
            $periodStart = strtotime($startText);
            $resolutionS = e3dc_entsoe_parse_resolution_s($resolutionText);
            if ($periodStart === false || $resolutionS <= 0) continue;

            $points = e3dc_entsoe_xml_blocks($period, 'Point');
            foreach ($points as $point) {
                $position = (int)e3dc_entsoe_xml_text($point, 'position');
                $priceRaw = e3dc_entsoe_xml_text($point, 'price.amount');
                if ($position <= 0 || $priceRaw === '' || !is_numeric($priceRaw)) continue;
                $start = $periodStart + (($position - 1) * $resolutionS);
                $slots[$start] = [
                    'start' => $start,
                    'end' => $start + $resolutionS,
                    'marketprice' => (float)$priceRaw,
                    'resolution_min' => (int)round($resolutionS / 60),
                ];
            }
        }
    }
    ksort($slots, SORT_NUMERIC);
    return ['success' => true, 'slots' => array_values($slots)];
}

function e3dc_entsoe_api_test($token) {
    $token = str_replace(["\r", "\n"], '', trim((string)$token));
    if ($token === '') {
        return ['success' => false, 'message' => 'Bitte zuerst einen ENTSO-E API-Token eintragen.'];
    }

    $params = [
        'securityToken' => $token,
        'documentType' => 'A44',
        'in_Domain' => '10Y1001A1001A82H',
        'out_Domain' => '10Y1001A1001A82H',
        'periodStart' => e3dc_entsoe_api_time(time() - 24 * 3600),
        'periodEnd' => e3dc_entsoe_api_time(time() + 48 * 3600),
    ];
    $endpoints = [
        'https://web-api.tp.entsoe.eu/api',
        'https://external-api.tp.entsoe.eu/api',
    ];
    $lastMessage = '';
    foreach ($endpoints as $endpoint) {
        $url = $endpoint . '?' . http_build_query($params);
        $context = stream_context_create([
            'http' => [
                'method' => 'GET',
                'header' => "User-Agent: E3DC-Control-V4/1.0\r\nAccept: application/xml\r\n",
                'timeout' => 15,
                'ignore_errors' => true,
            ],
        ]);
        $raw = @file_get_contents($url, false, $context);
        $statusCode = 0;
        if (isset($http_response_header) && is_array($http_response_header)) {
            foreach ($http_response_header as $headerLine) {
                if (preg_match('/^HTTP\/\S+\s+(\d+)/', (string)$headerLine, $m)) {
                    $statusCode = (int)$m[1];
                    break;
                }
            }
        }
        if ($raw === false || trim((string)$raw) === '') {
            $lastMessage = $statusCode > 0 ? "HTTP {$statusCode}" : 'keine Antwort';
            continue;
        }
        $parsed = e3dc_entsoe_parse_day_ahead_xml($raw);
        if (!$parsed['success']) {
            $lastMessage = $parsed['message'];
            continue;
        }
        $slots = $parsed['slots'];
        if (count($slots) === 0) {
            $lastMessage = 'keine Preisslots in der Antwort';
            continue;
        }

        $now = time();
        $current = null;
        $lastBeforeNow = null;
        $resolutions = [];
        foreach ($slots as $slot) {
            $resolutions[(int)$slot['resolution_min']] = true;
            if ($slot['start'] <= $now) $lastBeforeNow = $slot;
            if ($slot['start'] <= $now && $now < $slot['end']) {
                $current = $slot;
                break;
            }
        }
        if ($current === null) $current = $lastBeforeNow ?: $slots[0];
        $resolutionText = implode('/', array_keys($resolutions));
        $priceCt = ((float)$current['marketprice']) / 10.0;
        $startText = date('H:i', (int)$current['start']);
        return [
            'success' => true,
            'message' => 'Verbindung OK: ' . count($slots) . ' ENTSO-E-Preisslots (' . $resolutionText . '-Min) gelesen. Aktueller Marktpreis ' . e3dc_tibber_format_ct($priceCt) . ' ct/kWh ab ' . $startText . '.',
            'slots' => count($slots),
            'price_resolution_min' => array_keys($resolutions),
            'current_marketprice_eur_mwh' => round((float)$current['marketprice'], 3),
        ];
    }
    return ['success' => false, 'message' => 'ENTSO-E API nicht erreichbar oder ohne Preisdaten' . ($lastMessage !== '' ? ' (' . $lastMessage . ')' : '') . '.'];
}

function e3dc_tibber_api_test($token, $homeId = '') {
    $token = str_replace(["\r", "\n"], '', trim((string)$token));
    $homeId = trim((string)$homeId);
    if ($token === '') {
        return ['success' => false, 'message' => 'Bitte zuerst einen Tibber API-Token eintragen.'];
    }

    $query = <<<'GRAPHQL'
query E3dcTibberPrices {
  viewer {
    homes {
      id
      currentSubscription {
        priceInfo(resolution: QUARTER_HOURLY) {
          current { total energy tax startsAt level currency }
          today { total energy tax startsAt level currency }
          tomorrow { total energy tax startsAt level currency }
        }
      }
    }
  }
}
GRAPHQL;

    $payload = json_encode(['query' => $query], JSON_UNESCAPED_SLASHES);
    $context = stream_context_create([
        'http' => [
            'method' => 'POST',
            'header' => "Content-Type: application/json\r\nAuthorization: Bearer {$token}\r\nUser-Agent: E3DC-Control-V4/1.0\r\n",
            'content' => $payload,
            'timeout' => 12,
            'ignore_errors' => true,
        ],
    ]);

    $raw = @file_get_contents('https://api.tibber.com/v1-beta/gql', false, $context);
    $statusCode = 0;
    if (isset($http_response_header) && is_array($http_response_header)) {
        foreach ($http_response_header as $headerLine) {
            if (preg_match('/^HTTP\/\S+\s+(\d+)/', (string)$headerLine, $m)) {
                $statusCode = (int)$m[1];
                break;
            }
        }
    }
    if ($raw === false || trim((string)$raw) === '') {
        $suffix = $statusCode > 0 ? " (HTTP {$statusCode})" : '';
        return ['success' => false, 'message' => 'Tibber API nicht erreichbar' . $suffix . '.'];
    }

    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        return ['success' => false, 'message' => 'Tibber API hat keine gültige JSON-Antwort geliefert.'];
    }
    if (!empty($decoded['errors']) && is_array($decoded['errors'])) {
        $firstError = $decoded['errors'][0]['message'] ?? 'unbekannter API-Fehler';
        return ['success' => false, 'message' => 'Tibber API Fehler: ' . (string)$firstError];
    }

    $homes = $decoded['data']['viewer']['homes'] ?? [];
    if (!is_array($homes) || count($homes) === 0) {
        return ['success' => false, 'message' => 'Tibber API meldet kein Home für diesen Token.'];
    }

    $selectedHome = null;
    foreach ($homes as $home) {
        if (!is_array($home)) continue;
        if ($homeId !== '' && (string)($home['id'] ?? '') !== $homeId) continue;
        $priceInfo = $home['currentSubscription']['priceInfo'] ?? null;
        if (is_array($priceInfo)) {
            $selectedHome = $home;
            break;
        }
    }
    if ($selectedHome === null) {
        $msg = $homeId !== ''
            ? 'Tibber Home-ID nicht gefunden oder ohne Preisinfo.'
            : 'Kein Tibber Home mit Preisinfo gefunden.';
        return ['success' => false, 'message' => $msg];
    }

    $priceInfo = $selectedHome['currentSubscription']['priceInfo'] ?? [];
    $slots = [];
    foreach (['today', 'tomorrow'] as $dayKey) {
        $dayRows = $priceInfo[$dayKey] ?? [];
        if (!is_array($dayRows)) continue;
        foreach ($dayRows as $row) {
            if (is_array($row) && isset($row['total']) && is_numeric($row['total'])) {
                $slots[] = $row;
            }
        }
    }

    usort($slots, function($a, $b) {
        $startA = strtotime((string)($a['startsAt'] ?? '')) ?: 0;
        $startB = strtotime((string)($b['startsAt'] ?? '')) ?: 0;
        return $startA <=> $startB;
    });
    $now = time();
    $slotResolutionMin = null;
    $currentFromSlots = null;
    $lastSlotBeforeNow = null;
    $minDelta = null;
    foreach ($slots as $idx => $row) {
        $start = strtotime((string)($row['startsAt'] ?? ''));
        if ($start === false) continue;
        if ($idx + 1 < count($slots)) {
            $nextStart = strtotime((string)($slots[$idx + 1]['startsAt'] ?? ''));
            if ($nextStart !== false && $nextStart > $start) {
                $delta = $nextStart - $start;
                if ($minDelta === null || $delta < $minDelta) $minDelta = $delta;
            }
        }
        if ($start <= $now) $lastSlotBeforeNow = $row;
    }
    if ($minDelta !== null && $minDelta > 0) {
        $slotResolutionMin = (int)round($minDelta / 60);
    }
    foreach ($slots as $idx => $row) {
        $start = strtotime((string)($row['startsAt'] ?? ''));
        if ($start === false) continue;
        $end = $start + (($slotResolutionMin !== null && $slotResolutionMin > 0) ? $slotResolutionMin * 60 : 3600);
        if ($idx + 1 < count($slots)) {
            $nextStart = strtotime((string)($slots[$idx + 1]['startsAt'] ?? ''));
            if ($nextStart !== false && $nextStart > $start) $end = $nextStart;
        }
        if ($start <= $now && $now < $end) {
            $currentFromSlots = $row;
            break;
        }
    }
    $current = $currentFromSlots
        ?: $lastSlotBeforeNow
        ?: ((isset($priceInfo['current']) && is_array($priceInfo['current'])) ? $priceInfo['current'] : null);

    $homeSuffix = (string)($selectedHome['id'] ?? '') !== '' ? ' Home-ID erkannt.' : '';
    $resolutionSuffix = $slotResolutionMin !== null ? ' (' . $slotResolutionMin . '-Min)' : '';
    if (is_array($current) && isset($current['total']) && is_numeric($current['total'])) {
        $priceCt = ((float)$current['total']) * 100.0;
        $startText = '';
        $startTs = strtotime((string)($current['startsAt'] ?? ''));
        if ($startTs !== false) {
            $startText = ' ab ' . date('H:i', $startTs);
        }
        return [
            'success' => true,
            'message' => 'Verbindung OK: ' . count($slots) . ' Preis-Slots' . $resolutionSuffix . ' gelesen. Aktuell ' . e3dc_tibber_format_ct($priceCt) . ' ct/kWh' . $startText . '.' . $homeSuffix,
            'slots' => count($slots),
            'current_price_ct' => round($priceCt, 3),
            'price_resolution_min' => $slotResolutionMin,
            'home_id_detected' => (string)($selectedHome['id'] ?? '') !== '',
        ];
    }

    return [
        'success' => true,
        'message' => 'Verbindung OK: ' . count($slots) . ' Preis-Slots' . $resolutionSuffix . ' gelesen, aber kein aktueller Preis im API-Frame.',
        'slots' => count($slots),
        'price_resolution_min' => $slotResolutionMin,
        'home_id_detected' => (string)($selectedHome['id'] ?? '') !== '',
    ];
}

if (in_array(($_GET['config_action'] ?? ''), ['download', 'download_redacted'], true)) {
    requireWebAuth(false);
    $rawDownload = (($_GET['config_action'] ?? '') === 'download');
    $export_data = e3dc_read_existing_v4_json($v4_config_file_path);
    if ($export_data === null) {
        http_response_code(500);
        header('Content-Type: text/plain; charset=utf-8');
        echo "Konfiguration ist nicht lesbar.";
        exit;
    }
    if ($rawDownload && !e3dc_config_raw_download_pin_enabled($export_data)) {
        http_response_code(403);
        header('Content-Type: text/plain; charset=utf-8');
        echo "Raw-Config-Download ist erst verfügbar, wenn eine Web-PIN gesetzt ist. Nutze bis dahin den redigierten Download.";
        exit;
    }
    if ($rawDownload && (string)($_GET['raw_confirm'] ?? '') !== '1') {
        http_response_code(400);
        header('Content-Type: text/plain; charset=utf-8');
        echo "Roh-Config enthält Zugangsdaten, Tokens und RSCP-Passwörter. Bitte den Raw-Download nur über den bestätigten Button im Config-Editor starten.";
        exit;
    }
    unset($export_data['stop']);
    if (!$rawDownload) {
        $export_data = e3dc_config_redacted_export_data($export_data);
    }
    $host = preg_replace('/[^A-Za-z0-9_-]/', '', (string)(gethostname() ?: 'e3dc'));
    $export_data = [
        'format' => 'e3dc-control-v4-config',
        'version' => trim((string)@file_get_contents(__DIR__ . '/../VERSION')),
        'exported_at' => date(DATE_ATOM),
        'host' => $host,
        'redacted' => !$rawDownload,
        'config' => $export_data,
    ];
    $fileName = 'e3dc_config_' . ($rawDownload ? 'raw_' : 'redacted_') . ($host !== '' ? $host . '_' : '') . date('Ymd_His') . '.json';
    header('Content-Type: application/json; charset=utf-8');
    header('Content-Disposition: attachment; filename="' . $fileName . '"');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    echo json_encode($export_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    exit;
}

/* --- POST-LOGIK --- */
if ($configEditorRequestMethod === 'POST') {
    if (($_POST['config_action'] ?? '') === 'test_tibber_api') {
        requireWebAuth(false);
        header('Content-Type: application/json; charset=utf-8');
        $postedValues = (isset($_POST['values']) && is_array($_POST['values'])) ? $_POST['values'] : [];
        $token = $postedValues['tibber_api_token'] ?? ($_POST['tibber_api_token'] ?? '');
        $homeId = $postedValues['tibber_home_id'] ?? ($_POST['tibber_home_id'] ?? '');
        echo json_encode(e3dc_tibber_api_test($token, $homeId), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        exit;
    } elseif (($_POST['config_action'] ?? '') === 'test_entsoe_api') {
        requireWebAuth(false);
        header('Content-Type: application/json; charset=utf-8');
        $postedValues = (isset($_POST['values']) && is_array($_POST['values'])) ? $_POST['values'] : [];
        $token = $postedValues['entsoe_api_token'] ?? ($_POST['entsoe_api_token'] ?? '');
        echo json_encode(e3dc_entsoe_api_test($token), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        exit;
    } elseif (($_POST['config_action'] ?? '') === 'create_manual_backup') {
        $backup = e3dcCreateConfirmedV4Backup(
            $v4_config_file_path,
            'config_editor',
            [
                'backup_dir' => rtrim(e3dc_config_backup_dir(), '/'),
                'retention_class' => 'manual',
            ]
        );
        if (!empty($backup['success'])) {
            $retentionWarning = e3dc_config_retention_warning_html($backup);
            $messageClass = $retentionWarning === '' ? 'alert-success' : 'alert-warning';
            $message = "<div class='alert $messageClass py-2 border-0 mb-3 mx-2 animate__animated animate__fadeIn'>✓ Dauerhafte lokale Konfigurationssicherung angelegt. Sie wird von der automatischen Bereinigung nicht gelöscht.$retentionWarning</div>";
        } else {
            $status = htmlspecialchars((string)($backup['status'] ?? 'unknown'));
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2 animate__animated animate__shakeX'>⚠ Die dauerhafte Konfigurationssicherung konnte nicht bestätigt werden ($status). Der aktuelle Stand wurde nicht verändert.</div>";
        }
    } elseif (isset($_POST['test_telegram'])) {
        $postedValues = (isset($_POST['values']) && is_array($_POST['values'])) ? $_POST['values'] : [];
        $currentData = e3dc_read_existing_v4_json($v4_config_file_path);
        if ($currentData === null) {
            $telegramResult = [
                'success' => false,
                'message' => 'Die bestehende Konfiguration ist nicht lesbar.',
            ];
        } else {
            $telegramConfig = $currentData;
            foreach (['telegram_token', 'telegram_chat_id', 'telegram_device_name'] as $telegramKey) {
                if (array_key_exists($telegramKey, $postedValues) && !is_array($postedValues[$telegramKey])) {
                    $telegramConfig[$telegramKey] = trim((string)$postedValues[$telegramKey]);
                }
            }
            require_once __DIR__ . '/send_status_telegram.php';
            $telegramResult = e3dcSendTelegramTestMessage($telegramConfig);
        }
        if (!empty($telegramResult['success'])) {
            $message = "<div class='alert alert-success py-2 border-0 mb-3 mx-2 animate__animated animate__fadeIn'>✓ "
                . htmlspecialchars((string)$telegramResult['message'])
                . " Die übrigen Formularwerte wurden nicht gespeichert.</div>";
        } else {
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2 animate__animated animate__shakeX'>⚠ Telegram-Test fehlgeschlagen: "
                . htmlspecialchars((string)($telegramResult['message'] ?? 'unbekannter Fehler'))
                . " Die Konfiguration wurde nicht verändert.</div>";
        }
    } elseif (($_POST['config_action'] ?? '') === 'upload_config') {
        requireWebAuth(false);
        $upload = $_FILES['config_upload_file'] ?? null;
        $maxBytes = 2 * 1024 * 1024;
        if (!is_array($upload) || ($upload['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Keine lesbare Config-Datei hochgeladen.</div>";
        } elseif ((int)($upload['size'] ?? 0) <= 0 || (int)($upload['size'] ?? 0) > $maxBytes) {
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Config-Datei ist leer oder größer als 2 MB.</div>";
        } else {
            $raw = (string)@file_get_contents((string)$upload['tmp_name']);
            $raw = preg_replace('/^\xEF\xBB\xBF/', '', $raw);
            $decoded = @json_decode($raw, true);
            $import_data = e3dc_config_extract_import_payload($decoded);
            $current_data = e3dc_read_existing_v4_json($v4_config_file_path);
            if ($import_data === null) {
                $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Upload abgebrochen. Die Datei ist keine gültige E3DC-Control JSON-Konfiguration.</div>";
            } elseif ($current_data === null) {
                $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Bestehende Konfiguration ist nicht lesbar. Import abgebrochen.</div>";
            } else {
                unset($import_data['stop']);
                $mutation = e3dcMutateV4ConfigDetailed(
                    static function($boundCurrent) use ($import_data) {
                        $next = array_replace($boundCurrent, $import_data);
                        $next = e3dc_config_preserve_local_keys($boundCurrent, $next);
                        return ['success' => true, 'data' => $next];
                    },
                    'preimport',
                    $v4_config_file_path,
                    '/var/www/html/ramdisk/e3dc_config_cache.json'
                );
                if (!empty($mutation['success'])) {
                    $count = count($import_data);
                    $retentionWarning = e3dc_config_retention_warning_html($mutation);
                    $messageClass = $retentionWarning === '' ? 'alert-success' : 'alert-warning';
                    $message = "<div class='alert $messageClass py-2 border-0 mb-3 mx-2 animate__animated animate__fadeIn'>Konfiguration importiert ($count Werte). Lokale Installationspfade wurden beibehalten. Backup wurde bestätigt. Bitte IP-Adressen, HA-Rolle und aktive Dienste prüfen.$retentionWarning</div>";
                    $config = readConfig($v4_config_file_path);
                    unset($config['stop']);
                } else {
                    $status = (string)($mutation['status'] ?? 'unknown');
                    $detail = !empty($mutation['state_unknown'])
                        ? 'Die neue Konfiguration wurde veröffentlicht, ihr Cache-/Rückfallzustand konnte aber nicht sicher bestätigt werden.'
                        : (!empty($mutation['rolled_back'])
                            ? 'Der Import wurde nach einem Cachefehler vollständig zurückgesetzt.'
                            : 'Import vor dem Commit abgebrochen; die bestehende Konfiguration blieb erhalten.');
                    $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2 animate__animated animate__shakeX'>$detail Fehlercode: " . htmlspecialchars($status) . ". Bitte im Installationscenter „Rechte prüfen und reparieren“ ausführen.</div>";
                }
            }
        }
    } elseif (isset($_POST['restore_backup'])) {
        requireWebAuth(false);
        $backupName = basename((string)($_POST['backup_file'] ?? ''));
        $backup_dir = e3dc_config_backup_dir();
        $backupPath = $backup_dir . $backupName;
        if (!preg_match('/^e3dc_v4_(?:manual_)?\d{8}_\d{6}(?:_[A-Za-z0-9_-]+)?\.json$/', $backupName)
            || !is_array(e3dcRetentionRegularFileSnapshot($backupPath))) {
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Backup-Datei ist nicht gültig.</div>";
        } else {
            $raw = e3dcReadRegularFileBound($backupPath, 4 * 1024 * 1024);
            $decoded = @json_decode($raw, true);
            $backup_data = e3dc_config_extract_import_payload($decoded);
            if ($backup_data === null) {
                $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Backup ist keine gültige JSON-Konfiguration.</div>";
            } else {
                $current_data = e3dc_read_existing_v4_json($v4_config_file_path);
                if ($current_data === null) $current_data = [];
                $mutation = e3dcMutateV4ConfigDetailed(
                    static function($boundCurrent) use ($backup_data) {
                        $next = e3dc_config_preserve_local_keys($boundCurrent, $backup_data);
                        return ['success' => true, 'data' => $next];
                    },
                    'prerestore',
                    $v4_config_file_path,
                    '/var/www/html/ramdisk/e3dc_config_cache.json'
                );
                if (!empty($mutation['success'])) {
                    $retentionWarning = e3dc_config_retention_warning_html($mutation);
                    $messageClass = $retentionWarning === '' ? 'alert-success' : 'alert-warning';
                    $message = "<div class='alert $messageClass py-2 border-0 mb-3 mx-2 animate__animated animate__fadeIn'>Konfiguration aus Backup wiederhergestellt. Der vorherige Stand wurde bestätigt gesichert; lokale Installationspfade wurden beibehalten.$retentionWarning</div>";
                    $config = readConfig($v4_config_file_path);
                    unset($config['stop']);
                } else {
                    $status = (string)($mutation['status'] ?? 'unknown');
                    $detail = !empty($mutation['state_unknown'])
                        ? 'Die Wiederherstellung wurde veröffentlicht, ihr Cache-/Rückfallzustand konnte aber nicht sicher bestätigt werden.'
                        : (!empty($mutation['rolled_back'])
                            ? 'Die Wiederherstellung wurde nach einem Cachefehler vollständig auf den vorherigen Stand zurückgesetzt.'
                            : 'Wiederherstellung vor dem Commit abgebrochen; der aktuelle Stand blieb erhalten.');
                    $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2 animate__animated animate__shakeX'>$detail Fehlercode: " . htmlspecialchars($status) . ". Bitte im Installationscenter „Rechte prüfen und reparieren“ ausführen.</div>";
                }
            }
        }
    } elseif (isset($_POST['quick_toggle_key'])) {
        header('Content-Type: application/json; charset=utf-8');
        $allowedQuickToggles = ['predump_enable'];
        $quickKey = strtolower(trim((string)($_POST['quick_toggle_key'] ?? '')));
        if (!in_array($quickKey, $allowedQuickToggles, true)) {
            echo json_encode(['success' => false, 'message' => 'Schalter nicht erlaubt']);
            exit;
        }

        $v4_data = e3dc_read_existing_v4_json($v4_config_file_path);
        if ($v4_data === null) {
            echo json_encode(['success' => false, 'message' => 'Bestehende Konfiguration ist nicht lesbar. Bitte Rechte prüfen.']);
            exit;
        }
        unset($v4_data['stop']);
        $old_v4_data = $v4_data;
        $v4_data[$quickKey] = in_array(strtolower(trim((string)($_POST['quick_toggle_value'] ?? '0'))), ['1', 'true', 'yes', 'on'], true) ? 1 : 0;

        $mutation = saveE3dcConfigValuesDetailed(
            [$quickKey => $v4_data[$quickKey]],
            $v4_config_file_path,
            '/var/www/html/ramdisk/e3dc_config_cache.json'
        );
        $success = !empty($mutation['success']);
        $status = (string)($mutation['status'] ?? 'unknown');
        $retentionWarning = e3dc_config_retention_warning($mutation);
        echo json_encode([
            'success' => $success,
            'key' => $quickKey,
            'value' => $v4_data[$quickKey],
            'message' => $success
                ? ('Gespeichert' . ($retentionWarning !== ''
                    ? '. Hinweis zur Bereinigung: ' . $retentionWarning
                    : ''))
                : (!empty($mutation['state_unknown'])
                    ? 'Konfiguration wurde veröffentlicht, der Cache-/Rückfallzustand ist unklar. Bitte Rechte prüfen und reparieren.'
                    : (!empty($mutation['rolled_back'])
                        ? 'Änderung wurde nach einem Cachefehler vollständig zurückgesetzt.'
                        : 'Fehler vor dem Speichern (' . $status . '). Bitte Rechte prüfen und reparieren.'))
        ]);
        exit;
    }
    // Logik für "save_all" (Hauptspeicher-Button)
    elseif (isset($_POST['save_all']) && !isset($_POST['delete_key']) && !isset($_POST['add_key'])) {
        $posted_values = $_POST['values'] ?? [];
        $config_load_failed = false;
        $config_validation_failed = false;

        // Aktuelle V4-Daten aus der einzigen Wahrheitsquelle laden
        $v4_data = e3dc_read_existing_v4_json($v4_config_file_path);
        if ($v4_data === null) {
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2'>Fehler: Bestehende e3dc_v4.json ist nicht lesbar oder ungültig. Speichern abgebrochen, damit die Konfiguration nicht überschrieben wird.</div>";
            $v4_data = [];
            $posted_values = [];
            $config_load_failed = true;
        }
        unset($v4_data['stop']);
        $old_v4_data = $v4_data;

        // Alle geposteten Werte übernehmen & Typen konvertieren
        $guard_warnings = [];
        $posted_values = e3dc_config_editor_preserve_missing_wb2_type(
            $posted_values,
            $v4_data
        );
        $old_wp_type = e3dc_cfg_scalar($v4_data, 'wp_type', $defaults['wp_type'] ?? '-1');
        $new_wp_type = e3dc_cfg_scalar($posted_values, 'wp_type', $old_wp_type);
        $safe_wp_type = in_array($old_wp_type, ['0', '1', '3', '4', '5', '6'], true)
            ? $old_wp_type
            : e3dc_cfg_detect_native_wp_type($v4_data, $defaults['wp_type'] ?? '-1');
        $native_wp_configured = e3dc_cfg_native_wp_configured($v4_data)
            || e3dc_cfg_has_address($v4_data, 'luxtronik_ip')
            || e3dc_cfg_has_address($v4_data, 'idm_ip')
            || e3dc_cfg_has_address($v4_data, 'stiebel_isg_ip')
            || e3dc_cfg_has_address($v4_data, 'dimplex_ip');

        if ($new_wp_type === '-1' || strtolower($new_wp_type) === 'none') {
            $posted_values['wp_type'] = '-1';
        } elseif ($new_wp_type === '2') {
            $posted_values['wp_type'] = '2';
            $posted_values['heizstab'] = '1';
            $guard_warnings[] = 'Heizstab/BWWP wurde als Zusatzverbraucher gespeichert; der bestehende Wärmepumpen-Typ blieb erhalten.';
        } elseif ($native_wp_configured && in_array($new_wp_type, ['2', '3'], true) && $new_wp_type !== $old_wp_type) {
            $posted_values['wp_type'] = $old_wp_type;
            $guard_warnings[] = 'Der Wärmepumpen-Typ wurde nicht überschrieben, weil bereits eine native Luxtronik/IDM/Stiebel/Dimplex-Konfiguration vorhanden ist.';
        }

        if ($new_wp_type === '2') {
            $guard_warnings = [];
        }

        if (array_key_exists('shadow_snapshot_token', $posted_values)) {
            $shadowTokenPosted = trim((string)$posted_values['shadow_snapshot_token']);
            if ($shadowTokenPosted === '') {
                // Passwortfeld bleibt absichtlich leer und überschreibt ein
                // vorhandenes Peer-Geheimnis nicht.
                unset($posted_values['shadow_snapshot_token']);
            } elseif (preg_match('/\A[0-9a-fA-F]{64}\z/D', $shadowTokenPosted) !== 1) {
                unset($posted_values['shadow_snapshot_token']);
                $config_validation_failed = true;
                $guard_warnings[] = 'Shadow Snapshot Token nicht gespeichert: erforderlich sind exakt 64 Hex-Zeichen.';
            } else {
                $posted_values['shadow_snapshot_token'] = strtolower($shadowTokenPosted);
            }
        }

        foreach (['shadow_sync_interval_s', 'shadow_fetch_timeout_s', 'shadow_snapshot_max_age_s'] as $shadowDefaultKey) {
            if (array_key_exists($shadowDefaultKey, $posted_values)
                && trim((string)$posted_values[$shadowDefaultKey]) === ''
                && array_key_exists($shadowDefaultKey, $defaults)) {
                $posted_values[$shadowDefaultKey] = $defaults[$shadowDefaultKey];
            }
        }

        if (array_key_exists('frontend_variant', $posted_values)) {
            $frontendVariantPosted = strtolower(trim((string)$posted_values['frontend_variant']));
            $posted_values['frontend_variant'] = in_array($frontendVariantPosted, ['classic', 'modern'], true)
                ? $frontendVariantPosted
                : 'classic';
        }
        if (array_key_exists('frontend_detail_mode', $posted_values)) {
            $frontendDetailPosted = strtolower(trim((string)$posted_values['frontend_detail_mode']));
            $posted_values['frontend_detail_mode'] = in_array($frontendDetailPosted, ['compact', 'normal', 'detail'], true)
                ? $frontendDetailPosted
                : 'normal';
        }
        if (array_key_exists('config_secret_protection_mode', $posted_values)) {
            $posted_values['config_secret_protection_mode'] = e3dc_config_secret_mode($posted_values);
        }

        if (array_key_exists('stromtarif_typ', $posted_values)) {
            $postedTariffType = strtolower(trim((string)$posted_values['stromtarif_typ']));
            if ($postedTariffType === 'tibber') {
                $posted_values['tariff_provider'] = 'tibber';
            } elseif (array_key_exists('tariff_provider', $posted_values)) {
                $postedProvider = strtolower(trim((string)$posted_values['tariff_provider']));
                $posted_values['tariff_provider'] = in_array($postedProvider, ['smard', 'entsoe', 'awattar'], true)
                    ? $postedProvider
                    : 'smard';
            }
        }

        $plannedLoadWindowsPosted = null;
        if (isset($posted_values['planned_load_windows']) && is_array($posted_values['planned_load_windows'])) {
            $plannedLoadWindowsPosted = [];
            $plannedLoadMinPowerW = 2000;
            $plannedLoadMinDurationMin = 45;
            foreach ($posted_values['planned_load_windows'] as $idx => $row) {
                if (!is_array($row)) {
                    continue;
                }
                $rowVal = function($key, $default = '') use ($row) {
                    return trim((string)($row[$key] ?? $default));
                };
                $numberVal = function($key, $default = 0) use ($row) {
                    $raw = str_replace(',', '.', trim((string)($row[$key] ?? '')));
                    if ($raw === '' || !is_numeric($raw)) {
                        return $default;
                    }
                    return (int)round((float)$raw);
                };
                $parseTimeMin = function($value) {
                    $value = trim((string)$value);
                    if (!preg_match('/^([01]?\d|2[0-3]):([0-5]\d)$/', $value, $m)) {
                        return null;
                    }
                    return ((int)$m[1]) * 60 + (int)$m[2];
                };

                $name = $rowVal('name');
                $start = $rowVal('start');
                $end = $rowVal('end');
                $powerW = $numberVal('power_w', 0);
                $weekdays = $rowVal('weekdays');
                $enabled = in_array(strtolower($rowVal('enabled', '0')), ['1', 'true', 'yes', 'on', 'ja'], true);
                $deleteRow = in_array(strtolower($rowVal('delete', '0')), ['1', 'true', 'yes', 'on', 'ja'], true);
                $modeRaw = strtolower(str_replace(['-', ' '], '_', $rowVal('mode', 'protect_storage')));
                $mode = in_array($modeRaw, ['price_support', 'price_guided_support', 'preisgeführt_stuetzen'], true)
                    ? 'price_support'
                    : 'protect_storage';

                if ($deleteRow) {
                    continue;
                }

                if ($name === '' && $start === '' && $end === '' && $powerW <= 0 && $weekdays === '') {
                    continue;
                }
                $windowLabel = $name !== '' ? $name : ('Last ' . (count($plannedLoadWindowsPosted) + 1));
                if ($powerW > 0 && $powerW < $plannedLoadMinPowerW) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: geplante Lastfenster brauchen mindestens 2 kW.';
                    continue;
                }
                if ($enabled && ($start === '' || $end === '' || $powerW <= 0)) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: aktive Lastfenster brauchen Start, Ende und Leistung.';
                    continue;
                }
                if ($start === '' || $end === '' || $powerW <= 0) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: angefangene Lastfenster brauchen Start, Ende und Leistung.';
                    continue;
                }
                $startMin = $parseTimeMin($start);
                $endMin = $parseTimeMin($end);
                if ($startMin === null || $endMin === null) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: Zeitformat muss HH:MM sein.';
                    continue;
                }
                $durationMin = ($endMin - $startMin + 1440) % 1440;
                if ($durationMin <= 0) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: Start und Ende dürfen nicht gleich sein.';
                    continue;
                }
                if ($durationMin < $plannedLoadMinDurationMin) {
                    $guard_warnings[] = $windowLabel . ' wurde nicht gespeichert: Lastfenster müssen mindestens 45 Minuten dauern.';
                    continue;
                }

                $plannedWindow = [
                    'enabled' => $enabled,
                    'name' => $windowLabel,
                    'kind' => $rowVal('kind', 'external_load') ?: 'external_load',
                    'start' => $start,
                    'end' => $end,
                    'power_w' => max(0, $powerW),
                    'weekdays' => $weekdays,
                    'mode' => $mode,
                ];
                foreach ([
                    'min_power_w',
                    'min_duration_min',
                    'tolerance_w',
                    'confirm_grace_min',
                    'late_grace_min',
                    'early_grace_min',
                ] as $optionalKey) {
                    $optionalValue = max(0, $numberVal($optionalKey, 0));
                    if ($optionalValue > 0) {
                        $plannedWindow[$optionalKey] = $optionalValue;
                    }
                }
                $plannedWindow['min_power_w'] = $plannedLoadMinPowerW;
                $plannedWindow['min_duration_min'] = $plannedLoadMinDurationMin;
                $plannedLoadWindowsPosted[] = $plannedWindow;
            }
            unset($posted_values['planned_load_windows']);
        }

        $solcastMappingPost = e3dc_config_editor_normalize_solcast_slots($posted_values);
        $posted_values = $solcastMappingPost['values'];
        $solcastLegacyMappingsToRemove = $solcastMappingPost['remove'];
        if ($solcastMappingPost['invalid']) {
            $guard_warnings[] = 'Ungültige Solcast-Kontozuordnung wurde nicht gespeichert; zulässig sind nur Konto 1 oder 2.';
        }

        $topologyUiDirty = in_array(
            strtolower(trim((string)($_POST['pv_topology_ui_dirty'] ?? '0'))),
            ['1', 'true', 'yes', 'on'],
            true
        );
        $topology_to_save = null;
        if ($topologyUiDirty) {
            $topology_to_save = e3dc_config_editor_normalize_pv_topology(
                $posted_values['pv_forecast_topology_config'] ?? null,
                $topology_validation_error
            );
            if ($topology_to_save === null) {
                $config_validation_failed = true;
                $guard_warnings[] = 'PV-Topologie nicht gespeichert: ' . $topology_validation_error;
            }
        }
        // Ohne bewusste Änderung bleibt eine vorhandene Array-Konfiguration unverändert.
        unset($posted_values['pv_forecast_topology_config']);

        // Noch nicht freigegeben: Weder UI noch manipulierte POST-Daten dürfen
        // eine spätere Runtime- oder Plan-Action vorbereiten.
        $posted_values['storage_forecast_shortfall_aux_ac_charge_enable'] = '0';

        foreach ($posted_values as $key => $value) {
            if (is_array($value) || is_object($value)) {
                continue;
            }
            $value = trim($value);
            if ($value !== '' && is_numeric($value)) {
                $v4_data[$key] = (strpos($value, '.') !== false) ? floatval($value) : intval($value);
            } else {
                $v4_data[$key] = $value;
            }
        }
        if ($topologyUiDirty && !$config_validation_failed) {
            $v4_data['pv_forecast_topology_config'] = $topology_to_save;
        }
        foreach ($solcastLegacyMappingsToRemove as $mappingKey) {
            unset($v4_data[$mappingKey]);
        }
        $auxSuffixes = ['override', 'ip', 'invert', 'dynamic_unblock_enable', 'unblock_threshold_w'];
        $auxPosted = array_values(array_filter($auxSuffixes, function($suffix) use ($posted_values) {
            return array_key_exists('direct_marketing_aux_inverter_shelly_' . $suffix, $posted_values);
        }));
        if (count($auxPosted) === count($auxSuffixes)) {
            $v4_data['direct_marketing_aux_inverter_shelly_contract_status'] = 'ok';
            $v4_data['direct_marketing_aux_inverter_shelly_contract_reason'] = 'user_confirmed';
        } elseif (count($auxPosted) > 0) {
            $safeAux = [
                'override' => 'local',
                'ip' => '',
                'invert' => 0,
                'dynamic_unblock_enable' => 0,
                'unblock_threshold_w' => 3000,
            ];
            foreach ($safeAux as $suffix => $value) {
                $v4_data['direct_marketing_aux_inverter_shelly_' . $suffix] = $value;
            }
            $v4_data['direct_marketing_aux_inverter_shelly_contract_status'] = 'blocked';
            $v4_data['direct_marketing_aux_inverter_shelly_contract_reason'] = 'config_editor_partial_contract';
            $guard_warnings[] = 'Die unvollständige Zusatz-WR-Konfiguration wurde sicher deaktiviert; es wurden keine Shelly-Befehle freigegeben.';
        }
        if ($plannedLoadWindowsPosted !== null) {
            $v4_data['planned_load_windows'] = $plannedLoadWindowsPosted;
        }

        $normalize_wb_type_for_save = function($type) {
            $type = strtolower(trim((string)$type));
            $aliases = [
                'goe' => 'go-e',
                'openwb-pro' => 'openwb_pro',
                'openwbpro' => 'openwb_pro',
                'e3dc_multi_connect' => 'e3dc_multi',
                'e3dc-multi' => 'e3dc_multi',
                'e3dc multi' => 'e3dc_multi',
                'e3dc_easy' => 'e3dc',
                'e3dc_legacy' => 'e3dc',
                'native' => 'e3dc',
                'off' => 'none',
                'disabled' => 'none',
            ];
            return $aliases[$type] ?? $type;
        };
        if ($normalize_wb_type_for_save($v4_data['wb_native_type'] ?? '') !== 'openwb') {
            $v4_data['wb1_topic_prefix'] = '';
        }
        if (array_key_exists('wb_native_type2', $v4_data)
            && $normalize_wb_type_for_save($v4_data['wb_native_type2']) !== 'openwb') {
            $v4_data['wb2_topic_prefix'] = '';
        }

        $midTargetPosted = isset($v4_data['storage_mid_target_soc'])
            ? (float)$v4_data['storage_mid_target_soc']
            : 0.0;
        $noonTargetPosted = isset($v4_data['storage_noon_target_soc'])
            ? (float)$v4_data['storage_noon_target_soc']
            : 0.0;
        if ($midTargetPosted > 0.0 || $noonTargetPosted > 0.0) {
            // Ein Zwischenziel ohne Kurvenführung ist wirkungslos und erzeugt
            // Freilauf/Volladen. Beim Speichern konsistent halten.
            $v4_data['tl_enable'] = 1;
        }

        $success = false;
        $config_backup_failed = false;
        $config_cache_invalidation_failed = false;
        $config_state_unknown = false;
        $config_mutation_status = 'not_started';
        if (!$config_load_failed && !$config_validation_failed) {
            $mutation = e3dcMutateV4ConfigDetailed(
                static function($boundCurrent) use ($v4_data) {
                    return [
                        'success' => true,
                        'data' => e3dc_aux_inverter_prepare_config($v4_data),
                    ];
                },
                'save',
                $v4_config_file_path,
                '/var/www/html/ramdisk/e3dc_config_cache.json'
            );
            $success = !empty($mutation['success']);
            $config_mutation_status = (string)($mutation['status'] ?? 'unknown');
            $config_backup_failed = !empty($mutation['backup_failed'])
                || str_contains($config_mutation_status, 'backup_');
            $config_cache_invalidation_failed = str_contains($config_mutation_status, 'cache_');
            $config_state_unknown = !empty($mutation['state_unknown']);
            $retentionWarning = e3dc_config_retention_warning($mutation);
            if ($retentionWarning !== '') $guard_warnings[] = $retentionWarning;
        }

        if ($success) {
            $autoInstallConfirmed = in_array(strtolower(trim((string)($_POST['config_auto_install_confirmed'] ?? '0'))), ['1', 'true', 'yes', 'on'], true);
            $autoInstallCandidates = e3dc_config_auto_install_missing_candidates($v4_data, $old_v4_data);
            $auto_install_failed = false;
            if (!empty($autoInstallCandidates) && $autoInstallConfirmed) {
                foreach (e3dc_config_auto_install_missing_services($v4_data, $old_v4_data) as $autoInstall) {
                    $label = $autoInstall['label'] ?? ($autoInstall['module'] ?? 'Modul');
                    if (!empty($autoInstall['ok'])) {
                        $guard_warnings[] = $label . ' wurde nach deiner Bestätigung automatisch installiert, aktiviert oder neu gestartet, weil die zugehörige Konfiguration aktiv ist.';
                    } else {
                        $auto_install_failed = true;
                        $guard_warnings[] = $label . ' ist konfiguriert, konnte aber nicht automatisch installiert, aktiviert oder neu gestartet werden: ' . ($autoInstall['message'] ?? 'unbekannter Fehler') . '. Bitte Installationszentrale prüfen.';
                    }
                }
            } elseif (!empty($autoInstallCandidates)) {
                $labels = array_map(function($info) { return (string)($info['label'] ?? 'Modul'); }, $autoInstallCandidates);
                $guard_warnings[] = 'Konfiguration gespeichert; folgende Dienste wurden noch nicht installiert, gestartet oder neu gestartet, weil die Bestätigung fehlt: ' . implode(', ', $labels) . '. Beim nächsten Speichern bestätigen oder die Installationszentrale nutzen.';
            }
            $extra = '';
            if (!empty($guard_warnings)) {
                $extra = '<div class="small mt-1">' . implode('<br>', array_map('htmlspecialchars', $guard_warnings)) . '</div>';
            }
            $message_class = ($auto_install_failed || $retentionWarning !== '')
                ? 'alert-warning'
                : 'alert-success';
            $message_title = $auto_install_failed
                ? '⚠ Konfiguration gespeichert, Dienste nicht vollständig aktualisiert.'
                : ($retentionWarning !== ''
                    ? '⚠ Konfiguration gespeichert, automatische Altstände nicht vollständig bereinigt.'
                    : '✓ Konfiguration erfolgreich gespeichert.');
            $message = "<div class='alert $message_class py-2 border-0 mb-3 mx-2 animate__animated animate__fadeIn'>$message_title$extra</div>";
            $config = readConfig($v4_config_file_path);
            unset($config['stop']);
            $pv_topology_ui_state = e3dc_config_editor_pv_topology_ui_state($v4_data);
            $pv_topology_has_explicit_ui = $pv_topology_ui_state['has_explicit'];
            $pv_topology_stored_valid_ui = $pv_topology_ui_state['stored_valid'];
            $pv_topology_raw_ui = $pv_topology_ui_state['raw'];
            $pv_topology_json_ui = json_encode(
                $pv_topology_raw_ui,
                JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
            ) ?: '{}';
        } else {
            $failure_details = [];
            $config_prewrite_failed = in_array($config_mutation_status, [
                'identity_unavailable',
                'lock_directory_invalid',
                'lock_invalid',
                'lock_open_failed',
                'lock_metadata_invalid',
                'lock_failed',
            ], true);
            if ($config_load_failed) {
                $failure_details[] = 'Die vorhandene e3dc_v4.json ist nicht lesbar oder enthält kein gültiges JSON.';
            }
            if ($config_validation_failed) {
                $failure_details = array_merge($failure_details, $guard_warnings);
            }
            if ($config_backup_failed) {
                $failure_details[] = 'Die aktuelle Konfiguration konnte vor dem Speichern nicht gesichert werden. Bitte im Installationscenter zuerst „Nur Rechte prüfen“ und bei einem bestätigten Befund anschließend „System reparieren“ ausführen.';
            }
            if ($config_cache_invalidation_failed) {
                $failure_details[] = !empty($mutation['rolled_back'])
                    ? 'Die Änderung wurde nach einem Cachefehler vollständig auf den vorherigen Stand zurückgesetzt.'
                    : ($config_state_unknown
                        ? 'Die Konfiguration wurde veröffentlicht, ihr Cache-/Rückfallzustand konnte jedoch nicht sicher bestätigt werden.'
                        : 'Der Laufzeitcache konnte vor dem Speichern nicht sicher entfernt werden.');
            }
            if ($config_prewrite_failed) {
                $failure_details[] = 'Der Speichervorgang wurde vor dem Schreiben abgebrochen. Die bestehende Konfiguration blieb unverändert.';
            }
            if (!$config_load_failed
                && !$config_validation_failed
                && !$config_backup_failed
                && !$config_cache_invalidation_failed
                && !$config_prewrite_failed) {
                clearstatcache(true, $v4_config_file_path);
                if (!is_writable($v4_config_file_path)) {
                    $perms = @file_exists($v4_config_file_path)
                        ? substr(sprintf('%o', fileperms($v4_config_file_path)), -4)
                        : 'nicht vorhanden';
                    $failure_details[] = 'Keine Schreibrechte auf e3dc_v4.json (Modus: ' . $perms . ').';
                } else {
                    $failure_details[] = 'Die validierte Konfiguration konnte nicht vollständig geschrieben oder bestätigt werden.';
                }
            }
            $failure_details = array_values(array_unique(array_filter(array_map('strval', $failure_details))));
            if (!$config_load_failed && !$config_validation_failed && $config_mutation_status !== 'not_started') {
                $failure_details[] = 'Fehlercode: ' . $config_mutation_status . '. Bitte im Installationscenter zuerst „Nur Rechte prüfen“ und bei einem bestätigten Rechtefehler „System reparieren“ ausführen.';
            }
            $failure_details = array_values(array_unique(array_filter(array_map('strval', $failure_details))));
            $failure_html = $failure_details
                ? '<div class="small mt-1">' . implode('<br>', array_map('htmlspecialchars', $failure_details)) . '</div>'
                : '';
            $message = "<div class='alert alert-danger py-2 border-0 mb-3 mx-2 animate__animated animate__shakeX'>⚠ Konfiguration nicht gespeichert.$failure_html</div>";
        }
    }
}

$groups = [
    "V4 Smart Home (Regelung & KI)" => [
        "luxtronik", "wp_type", "wp_source_type", "idm_ip", "idm_port", "idm_e_total", "luxtronik_ip",
        "heizstab", "heizstab_type", "heizstab_ip", "heizstab_port", "heizstab_max_w", "shelly_heiz_ip", "shelly_heiz_w", "hs_min_surplus_w", "hs_min_soc", "hs_auto_mode",
        "climate_enable", "climate_name", "climate_meter_ip", "climate_meter_type", "climate_meter_phase", "climate_min_power_w", "climate_poll_s", "climate_history_enable", "climate_history_interval_s", "climate_forecast_enable",
        "climate_control_enable", "climate_control_provider", "climate_control_mode", "climate_control_poll_s", "climate_toshiba_cloud_enable", "climate_toshiba_username", "climate_toshiba_password", "climate_toshiba_device_ids", "climate_day_temp_c", "climate_night_temp_c", "climate_night_start", "climate_night_end", "climate_night_eco_enable", "climate_night_quiet_enable", "climate_high_power_enable",
        "shelly_3em_ip", "shelly_3em_relay_id", "shelly_3em_wp_min_w", "shelly_3em_wp_max_w", "shelly_3em_enable",
        "stiebel_isg_ip", "stiebel_isg_port", "stiebel_isg_device_id", "stiebel_isg_power_heating_w", "stiebel_isg_power_dhw_w",
        "stiebel_isg_standby_w", "stiebel_isg_max_hz", "stiebel_isg_hz_power_map", "stiebel_isg_scrape_hz_enable",
