                    <?php
                        if (!function_exists('parseFC')) {
                            function parseFC($s) {
                                $p = explode('/', trim($s));
                                return [
                                    'n' => isset($p[0]) ? floatval($p[0]) : 35,
                                    'a' => isset($p[1]) ? floatval($p[1]) : 0,
                                    'k' => isset($p[2]) ? floatval($p[2]) : 0,
                                ];
                            }
                        }
                        // FC1 immer anzeigen, FC2/3 nur bei Konfiguration (schrittweise Offenlegung).
